create table chaos_process_definition (tenant_id varchar(200) not null, process_code varchar(200) not null, definition_version integer not null, definition_json clob not null, primary key (tenant_id, process_code, definition_version));
create table chaos_process_instance (instance_id varchar(64) primary key, tenant_id varchar(200) not null, process_code varchar(200) not null, definition_version integer not null, business_type varchar(200) not null, business_id varchar(200) not null, status varchar(32) not null, instance_json clob not null);
create unique index chaos_process_active_uq on chaos_process_instance(tenant_id, process_code, business_type, business_id, status);
create table chaos_process_task (task_id varchar(64) primary key, instance_id varchar(64) not null, tenant_id varchar(200) not null, node_key varchar(200) not null, status varchar(32) not null, assignee_id varchar(200), claim_expires_at timestamp, completed_at timestamp, completion_event varchar(200), comment clob, version bigint not null, created_at timestamp not null, task_json clob not null);
create index chaos_process_task_active_ix on chaos_process_task(instance_id, status);
create table chaos_process_request (tenant_id varchar(200) not null, request_id varchar(200) not null, request_type varchar(32) not null, entity_id varchar(64) not null, command_json clob not null, primary key (tenant_id, request_id));
